# When an allocation is vacated, the room has one more free bed.
if record["room"]:
    room = records.get("camp_room", record["room"])
    if room is not None and (room["occupied"] or 0) > 0:
        room.update({"occupied": room["occupied"] - 1})
        log(f"Room {room['room_no']}: {room['occupied']} occupied")
